UPDATE `npc_text` SET `text4_0` = '很久以前，我在旅途中遇到一个人，他对我说：“先掌握它，然后你就能拥有这个了。”$B$B你觉得那是什么意思？我当时不懂，现在也不太懂……' WHERE `ID` = 2634 AND `text4_0` = 'A long time ago, during my travels, I met a man that told me, Master using it and you can have this.$B$BWhat do you suppose that means? I didn''t know then, and I still don''t now, really...';
UPDATE `npc_text` SET `text5_0` = '这是对所有人的秘密……包括我在内！$B$B很高兴你找到了我——还好我没躲在灌木丛或石头底下，对吧？' WHERE `ID` = 2634 AND `text5_0` = 'It''s a secret to everybody... including me!$B$BI''m glad you found me -- it''s a good thing I''m not hiding in a bush or underneath a rock, isn''t it?';
UPDATE `npc_text` SET `text4_0` = '水元素正与火元素交战，某种意义上也可以说是在与我们交战。他们的首领之一海达克西斯正在招募代理人……' WHERE `ID` = 2636 AND `text4_0` = 'The water elementals are at war with the fire elementals, which sort of means they''re at war with us.  One of their leaders, Hydraxis, is mustering agents for his cause...';
UPDATE `npc_text` SET `text4_1` = '水元素正与火元素交战，某种意义上也可以说是在与我们交战。他们的首领之一海达克西斯正在招募代理人……' WHERE `ID` = 2636 AND `text4_1` = 'The water elementals are at war with the fire elementals, which sort of means they''re at war with us.  One of their leaders, Hydraxis, is mustering agents for his cause...';
