UPDATE `npc_text` SET `text4_0` = '一定要告诉冬天爷爷这个冬幕节你想要什么神秘惊喜！' WHERE `ID` = 6194 AND `text4_0` = 'Be sure to tell Greatfather Winter what secret surprise you''d like to get this Winter Veil!';
