UPDATE `npc_text` SET `text5_0` = '别让铃儿的叮当声盖过你口袋里的叮当声！为你的冬幕节庆典买些烟林牧场的点心吧！' WHERE `ID` = 6194 AND `text5_0` = 'Don''t let the jingle of the bells take away from the jingle in your pocket!  Buy Smokywood Pastures treats for your Winter Veil festivities!';
