UPDATE `npc_text` SET `text6_0` = '要是我有栗子，你尽管相信我会把它们架在火上烤。嗯～！' WHERE `ID` = 6194 AND `text6_0` = 'If I had some chestnuts, you''d better believe I''d have them roasting over an open fire.  Mmmm!';
