UPDATE `npc_text` SET `text7_0` = '这个节日季别忘了囤些包装纸！没有什么比把护甲和武器包好送给亲友更能体现“奇妙冬幕节”了。' WHERE `ID` = 6194 AND `text7_0` = 'Don''t forget to stock up on wrapping paper this holiday season!  Nothing says "Wondrous Winter Veil" like wrapped armors and weapons for your friends and family.';
