UPDATE `npc_text` SET `text4_0` = '最近书籍接连失踪。博学者和他的助手们乱成一团，他们怀疑埃雷萨拉斯内有人作梗。' WHERE `ID` = 6911 AND `text4_0` = 'Books have been disappearing as of late. The Lorekeeper and his assistants are in a frenzy. They suspect foul play within Eldre''Thalas.';
