UPDATE `npc_text` SET `text7_0` = '主人对奈法利安的巢穴很感兴趣。要是有人能击败那条龙和他的爪牙，并把故事讲给王子听就好了。我敢打赌那会让王子松口。灰烬使者就能被找到了！' WHERE `ID` = 6911 AND `text7_0` = 'The Master holds great interest in the lair of Nefarian. If only someone would defeat the dragon and his minions and retell the tale to the Prince. I bet that would loosen the Prince''s lips. The Ashbringer could be found!';
UPDATE `npc_text` SET `text7_1` = '主人对奈法利安的巢穴很感兴趣。要是有人能击败那条龙和他的爪牙，并把故事讲给王子听就好了。我敢打赌那会让王子松口。灰烬使者就能被找到了！' WHERE `ID` = 6911 AND `text7_1` = 'The Master holds great interest in the lair of Nefarian. If only someone would defeat the dragon and his minions and retell the tale to the Prince. I bet that would loosen the Prince''s lips. The Ashbringer could be found!';
UPDATE `npc_text` SET `text4_0` = '只要你留在这儿和我们一起，你就是国王。你要是走了，别的食人魔就会取代你。这就是戈多克的方式！' WHERE `ID` = 6922 AND `text4_0` = 'So long as you stay here with us, you da king.  You take off, and some other ogre will take your place.  That''s da way of da Gordok!';
UPDATE `npc_text` SET `text5_0` = '我可聪明了！聪—明—人！' WHERE `ID` = 6922 AND `text5_0` = 'I am so smart!  S-M-R-T!';
UPDATE `npc_text` SET `text6_0` = '老国王死了？那不可能！' WHERE `ID` = 6922 AND `text6_0` = 'Old king got dead?  That''s unpossible!';
UPDATE `npc_text` SET `text7_0` = '我不会给你添麻烦的，老大。' WHERE `ID` = 6922 AND `text7_0` = 'I cause you no trouble, boss.';
