UPDATE `npc_text` SET `text5_0` = '我需要第二个脑袋，就像我需要丢掉第一个脑袋一样。' WHERE `ID` = 7338 AND `text5_0` = 'I need a second head like I need to lose my first one.';
UPDATE `npc_text` SET `text6_0` = '我在厄运之槌住过一阵子。挺有意思的。真的。' WHERE `ID` = 7338 AND `text6_0` = 'I lived in Dire Maul for a little bit.  That was fun.  Really.';
