UPDATE `npc_text` SET `text7_0` = '你能相信那个埃莉莎拉·阳击有多大胆吗？她以为她能吸引萨尔瑟瑞尔领主的注意？还有你看到她的穿着了吗？太上一季了。真是可悲。' WHERE `ID` = 8760 AND `text7_0` = 'Can you believe the nerve of that Elisara Sunstriker?  Thinking that she can catch the eye of Lord Saltheril?  And did you see what she''s wearing?  So last season.  It''s sad, really.';
