UPDATE `npc_text` SET `text5_0` = '不知道我们身边还藏着多少这样的人。我认识斯帕克多年——从没想到他竟是叛徒。' WHERE `ID` = 8892 AND `text5_0` = 'I wonder how many more of them live among us. I knew Spark for years - never could I have imagined that he was a traitor.';
