UPDATE `npc_text` SET `text5_0` = '我见你到处蹦跶。何不帮我们个忙，直接把装备丢到军械库去？' WHERE `ID` = 8961 AND `text5_0` = 'I''ve seen you prancing around.  Why don''t you do us all a favor and just drop your gear off at the armory?';
