UPDATE `npc_text` SET `text7_0` = '哎呀呀，看看这是什么？一个 $T civilian : civilian;？多可爱啊？我这儿可没什么特殊待遇给你！' WHERE `ID` = 8961 AND `text7_0` = 'Well, well, well, what have we here?  A $T civilian : civilian;?  Isn''t that precious?  You''ll get no special treatment from me!';
UPDATE `npc_text` SET `text4_0` = '大家都去哪儿了？' WHERE `ID` = 9383 AND `text4_0` = 'Where did everyone go?';
UPDATE `npc_text` SET `text5_0` = '晚宴的客人应该更懂得尊重！' WHERE `ID` = 9383 AND `text5_0` = 'Dinner guests should show more respect!';
